import z3
import itertools
import time

# Problem parameters
num_golfers = 27
num_weeks = 7
group_size = 3
num_groups = 9

# Variables: x[w][p] = group of player p in week w (0..8)
x = {}
for w in range(num_weeks):
    for p in range(num_golfers):
        x[w, p] = z3.Int(f"x_{w}_{p}")

s = z3.Solver()

# Domain constraints
for w in range(num_weeks):
    for p in range(num_golfers):
        s.add(x[w, p] >= 0)
        s.add(x[w, p] < num_groups)

# Each week, each group has exactly 3 players
for w in range(num_weeks):
    for g in range(num_groups):
        players_in_group = [z3.If(x[w, p] == g, 1, 0) for p in range(num_golfers)]
        s.add(sum(players_in_group) == group_size)

# No pair of golfers may be in the same group on more than one week
for p1 in range(num_golfers):
    for p2 in range(p1 + 1, num_golfers):
        same_group_count = []
        for w in range(num_weeks):
            same_group_count.append(z3.If(x[w, p1] == x[w, p2], 1, 0))
        s.add(sum(same_group_count) <= 1)

# Symmetry breaking: fix player 0 to group 0 in week 0
s.add(x[0, 0] == 0)
s.add(x[0, 1] == 0)
s.add(x[0, 2] == 0)
s.add(x[0, 3] == 1)
s.add(x[0, 4] == 1)
s.add(x[0, 5] == 1)

print("Constraints added, solving...")
start = time.time()
result = s.check()
print(f"Result: {result}, time: {time.time() - start:.2f}s")

if result == z3.sat:
    m = s.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            solution.append(m.evaluate(x[w, p]).as_long())
    print("Solution found!")

    # Verify
    def verify(sol):
        for w in range(num_weeks):
            week = sol[w*27:(w+1)*27]
            for g in range(num_groups):
                count = week.count(g)
                if count != 3:
                    print(f"Week {w}, group {g}: {count} players (expected 3)")
                    return False

        pair_count = {}
        for w in range(num_weeks):
            week = sol[w*27:(w+1)*27]
            groups = {g: [] for g in range(num_groups)}
            for p in range(num_golfers):
                groups[week[p]].append(p)

            for g in range(num_groups):
                players = groups[g]
                for i in range(len(players)):
                    for j in range(i+1, len(players)):
                        pair = tuple(sorted((players[i], players[j])))
                        if pair in pair_count:
                            print(f"Pair {pair} appears together in week {pair_count[pair]} and week {w}")
                            return False
                        pair_count[pair] = w

        print(f"All {len(pair_count)} pairs verified")
        return True

    print("Verification:", verify(solution))
    print("\nFull solution:")
    print(solution)
else:
    print("No solution found")
